package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.*;import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import software.bernie.geckolib.renderer.GeoItemRenderer;import software.bernie.geckolib.model.GeoModel;import software.bernie.geckolib.cache.object.GeoBone;import com.atsuishio.superbwarfare.data.gun.GunData;
public class Dil01ItemRenderer extends GeoItemRenderer<Dil01Item> implements FastMeshRenderer<Dil01Item> {
 private static Dil01ItemRenderer instance;public static Dil01ItemRenderer instance(){if(instance==null)instance=new Dil01ItemRenderer();return instance;}
 private static ResourceLocation id(String p){return ResourceLocation.fromNamespaceAndPath(SbwDroneRangeConfig.MOD_ID,p);}
 public Dil01ItemRenderer(){super(new GeoModel<>(){@Override public ResourceLocation getModelResource(Dil01Item e){return id("geo/drone_interceptor_launcher_dil01.geo.json");}@Override public ResourceLocation getTextureResource(Dil01Item e){return id("textures/item/drone_interceptor_launcher_dil01.png");}@Override public ResourceLocation getAnimationResource(Dil01Item e){return id("animations/drone_interceptor_launcher_dil01.animation.json");}});}
 @Override public ResourceLocation getTextureLocation(Dil01Item e){boolean locked=false;if(currentItemStack!=null&&Dil01Item.is(currentItemStack)){var d=GunData.from(currentItemStack);var l=Minecraft.getInstance().level;locked=l!=null&&d.data().getBoolean("DILLocked")&&!d.reloading()&&l.getGameTime()-d.data().getLong("DILStamp")<=12;}return id("textures/item/drone_interceptor_launcher_dil01"+(locked?"_locked":"")+".png");}
 @Override public RenderType getRenderType(Dil01Item e,ResourceLocation t,MultiBufferSource b,float partial){return RenderType.entityCutoutNoCull(t);}
 @Override public void renderRecursively(PoseStack p,Dil01Item e,GeoBone bone,RenderType t,MultiBufferSource b,VertexConsumer v,boolean rerender,float partial,int light,int overlay,int color){if(currentItemStack!=null){var d=GunData.from(currentItemStack);switch(bone.getName()){case "trigger"->bone.setRotX((float)Math.toRadians(d.shootAnimationTimer.get()>0?-11:0));case "safety_switch"->bone.setRotX((float)Math.toRadians(d.zooming.get()?22:0));case "rear_cap"->bone.setRotX((float)Math.toRadians(d.reloading()?-72*Math.sin(Math.PI*Math.min(1,d.reload.time()/78d)):0));}}super.renderRecursively(p,e,bone,t,b,v,rerender,partial,light,overlay,color);}
 public void nativeModel(ItemStack s,PoseStack p,MultiBufferSource b,int light,int overlay){p.pushPose();p.translate(-.5,-.51,-.5);super.renderByItem(s,ItemDisplayContext.NONE,p,b,light,overlay);p.popPose();}
 @Override public void renderByItem(ItemStack s,ItemDisplayContext context,PoseStack p,MultiBufferSource b,int light,int overlay){p.pushPose();p.translate(.5,.5,.5);boolean third=context==ItemDisplayContext.THIRD_PERSON_LEFT_HAND||context==ItemDisplayContext.THIRD_PERSON_RIGHT_HAND;if(third&&Dil01Pose.apply(p)){}else if(context==ItemDisplayContext.GROUND){p.translate(0,.263,0);p.scale(.65f,.65f,.65f);}else {p.mulPose(com.mojang.math.Axis.YP.rotationDegrees(90));p.scale(.6f,.6f,.6f);}p.translate(-.5,-.51,-.5);super.renderByItem(s,context,p,b,light,overlay);p.popPose();}
}
